const citationCountElements=document.querySelectorAll("[data-semantic-scholar-id]");citationCountElements.forEach(t=>{const a=t.getAttribute("data-semantic-scholar-id");a&&t.setAttribute("data-semantic-scholar-id",a.toLowerCase())});const semanticScholarIds=new Set(Array.from(citationCountElements).map(t=>t.getAttribute("data-semantic-scholar-id")).filter(t=>t));let uncachedSemanticScholarIds=[];semanticScholarIds.forEach(t=>{const a=`semanticScholarCitationCount:${t}`,o=localStorage.getItem(a);if(o){const{_:a,timestamp:e}=JSON.parse(o);Date.now()-e>36e5&&uncachedSemanticScholarIds.push(t)}else uncachedSemanticScholarIds.push(t)});let showSemanticScholarCitationCount=()=>{semanticScholarIds.forEach(t=>{const a=`semanticScholarCitationCount:${t}`,o=localStorage.getItem(a);if(o){const{citationCount:a}=JSON.parse(o);document.querySelectorAll(`[data-semantic-scholar-id="${t}"]`).forEach(o=>{o.innerHTML=`<a class="badge badge-pill badge-publication badge-info" href="https://www.semanticscholar.org/paper/${t}" target="_blank"><i class="ai ai-semantic-scholar"></i> ${parseInt(a).toLocaleString()} citations</a>`})}})};uncachedSemanticScholarIds.length>0?fetch("https://api.semanticscholar.org/graph/v1/paper/batch?fields=citationCount",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({ids:Array.from(semanticScholarIds)})}).then(t=>t.json()).then(t=>{t.forEach(t=>{console.log(t);const a=`semanticScholarCitationCount:${t.paperId}`,o={citationCount:t.citationCount,timestamp:Date.now()};localStorage.setItem(a,JSON.stringify(o))})}).catch(t=>{console.error("Error fetching Semantic Scholar data:",t)}).finally(showSemanticScholarCitationCount):showSemanticScholarCitationCount();